import CryptoKit
import Foundation

/// Executes HTTP requests generated by the core (cloud storage backup). The contract is in `kakey-ffi`'s `cloud.rs`: send
/// as-is, never follow redirects (3xx goes back to the core to check same-origin), no cookies, no cache, and read at most
/// limit + 1 bytes of the body. Transport failures (offline, timeout) throw `URLError`. When the system does not trust the
/// server certificate, the request's pinned certificate decides (docs/SECURITY.md); if it cannot be accepted,
/// this throws `CloudCertificateError`.
protocol HTTPExecuting: Sendable {
    func execute(_ request: CoreHttpRequest) async throws -> CoreHttpResponse
}

final class URLSessionHTTPExecutor: HTTPExecuting {
    private let session: URLSession
    private let maxBodyBytes: Int

    /// `configuration` exists only so tests can inject `protocolClasses`; production uses the default ephemeral session.
    init(configuration: URLSessionConfiguration = .ephemeral, maxBodyBytes: Int = Int(coreCloudMaxBodyBytes())) {
        configuration.httpCookieStorage = nil
        configuration.httpShouldSetCookies = false
        configuration.httpCookieAcceptPolicy = .never
        configuration.urlCache = nil
        configuration.requestCachePolicy = .reloadIgnoringLocalAndRemoteCacheData
        configuration.timeoutIntervalForRequest = 30
        configuration.timeoutIntervalForResource = 300
        configuration.waitsForConnectivity = false
        session = URLSession(configuration: configuration)
        self.maxBodyBytes = maxBodyBytes
    }

    deinit {
        session.invalidateAndCancel()
    }

    func execute(_ request: CoreHttpRequest) async throws -> CoreHttpResponse {
        guard let url = URL(string: request.url), let scheme = url.scheme?.lowercased(), scheme == "https" || scheme == "http",
            url.host != nil
        else { throw URLError(.badURL) }
        var urlRequest = URLRequest(url: url)
        urlRequest.httpMethod = request.method
        urlRequest.httpShouldHandleCookies = false
        for header in request.headers {
            urlRequest.setValue(header.value, forHTTPHeaderField: header.name)
        }
        if !request.body.isEmpty {
            urlRequest.httpBody = request.body
        }

        let delegate = RequestDelegate(pinnedCertificate: request.pinnedCertificate)
        let bytes: URLSession.AsyncBytes
        let response: URLResponse
        do {
            (bytes, response) = try await session.bytes(for: urlRequest, delegate: delegate)
        } catch {
            // Rejected in the certificate challenge: report the certificate error (with fingerprint), not a generic "cancelled".
            if let rejection = delegate.rejection { throw rejection }
            throw error
        }
        guard let http = response as? HTTPURLResponse else { throw URLError(.badServerResponse) }
        var body = Data()
        if http.expectedContentLength > 0 {
            body.reserveCapacity(min(Int(http.expectedContentLength), maxBodyBytes + 1))
        }
        for try await byte in bytes {
            body.append(byte)
            // Read one extra byte so the core can report "response too large" without loading a huge body into memory.
            if body.count > maxBodyBytes { break }
        }
        let headers = http.allHeaderFields.compactMap { key, value -> CoreHttpHeader? in
            guard let name = key as? String else { return nil }
            return CoreHttpHeader(name: name, value: "\(value)")
        }
        return CoreHttpResponse(status: UInt16(clamping: http.statusCode), headers: headers, body: body)
    }
}

/// The server certificate cannot be verified by system trust (see docs/SECURITY.md). `fingerprint` is the SHA-256 of the
/// server leaf certificate's DER.
enum CloudCertificateError: Error, Equatable {
    /// No pinned certificate: the UI asks the user to verify the fingerprint and decide whether to trust it.
    case untrusted(fingerprint: Data)
    /// The pinned certificate differs from the one presented: possibly a man-in-the-middle, so the user must go back to the
    /// connection screen and verify again; there is no one-tap trust.
    case changed(fingerprint: Data)
}

/// Decision for a server certificate challenge (docs/SECURITY.md). If the system trusts the certificate, proceed
/// as usual; otherwise accept only a certificate matching the pinned one.
enum ServerTrustDecision: Equatable {
    /// Let the system handle it: either the system trusts the certificate (regardless of the pin, so a server that switches
    /// to a proper certificate just works), or no certificate is available (the system fails as usual).
    case systemDefault
    /// The system does not trust it, but the leaf is exactly the certificate the user confirmed. The host name is not checked
    /// here, since self-signed certificates often carry the wrong host name or IP.
    case acceptPinned
    case reject(CloudCertificateError)

    static func decide(systemTrusted: Bool, leafFingerprint: Data?, pinned: Data?) -> Self {
        guard !systemTrusted, let leafFingerprint else { return .systemDefault }
        guard let pinned else { return .reject(.untrusted(fingerprint: leafFingerprint)) }
        return constantTimeEqual(leafFingerprint, pinned) ? .acceptPinned : .reject(.changed(fingerprint: leafFingerprint))
    }

    /// Constant-time comparison: timing does not depend on the position of the first differing byte.
    static func constantTimeEqual(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var difference: UInt8 = 0
        for (x, y) in zip(a, b) { difference |= x ^ y }
        return difference == 0
    }
}

/// One per request: refuses automatic redirects (3xx goes back to the core as-is, which accepts only same-origin,
/// non-downgrading redirects) and handles server certificate challenges against the pinned certificate.
private final class RequestDelegate: NSObject, URLSessionTaskDelegate, @unchecked Sendable {
    private let pinnedCertificate: Data?
    private let lock = NSLock()
    private var recordedRejection: CloudCertificateError?

    init(pinnedCertificate: Data?) {
        self.pinnedCertificate = pinnedCertificate
    }

    /// Why the certificate was rejected in the challenge; the request then fails as "cancelled".
    var rejection: CloudCertificateError? {
        lock.withLock { recordedRejection }
    }

    func urlSession(
        _ session: URLSession, task: URLSessionTask, willPerformHTTPRedirection response: HTTPURLResponse, newRequest request: URLRequest
    ) async -> URLRequest? {
        nil
    }

    func urlSession(
        _ session: URLSession, task: URLSessionTask, didReceive challenge: URLAuthenticationChallenge
    ) async -> (URLSession.AuthChallengeDisposition, URLCredential?) {
        guard challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
            let trust = challenge.protectionSpace.serverTrust
        else { return (.performDefaultHandling, nil) }
        let systemTrusted = SecTrustEvaluateWithError(trust, nil)
        let leaf = (SecTrustCopyCertificateChain(trust) as? [SecCertificate])?.first
        let fingerprint = leaf.map { Data(SHA256.hash(data: SecCertificateCopyData($0) as Data)) }
        switch ServerTrustDecision.decide(systemTrusted: systemTrusted, leafFingerprint: fingerprint, pinned: pinnedCertificate) {
        case .systemDefault:
            return (.performDefaultHandling, nil)
        case .acceptPinned:
            return (.useCredential, URLCredential(trust: trust))
        case .reject(let error):
            lock.withLock { recordedRejection = error }
            return (.cancelAuthenticationChallenge, nil)
        }
    }
}
